&lt;li&gt;&lt;span lang=&quot;en-GB&quot;&gt;Support our&amp;nbsp;&lt;/span&gt;&lt;span lang=&quot;en-US&quot;&gt;agile product development&amp;nbsp;&lt;/span&gt;&lt;span lang=&quot;en-US&quot;&gt;approach&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span lang=&quot;en-GB&quot;&gt;  &lt;/span&gt;&lt;span lang=&quot;en-US&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span lang=&quot;en-US&quot;&gt;What you need to succeed:&lt;/span&gt;&lt;span lang=&quot;en-US&quot;&gt;  &amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
